          m_pipa = m_A1 * gen::clamp((0.42 - m_f16 * 1.0 / m_sr) * 12.0, 0.0, 1.0) * m_s1 + m_A2 * gen::clamp((0.42 - m_f16 * 2.0 / m_sr) * 12.0, 0.0, 1.0) * m_s2 + m_A3 * (1.0 + m_ljv * 0.1462) * gen::clamp((0.42 - m_f16 * 3.0 / m_sr) * 12.0, 0.0, 1.0) * m_s3 + m_A4 * (1.0 + m_ljv * 0.2500) * gen::clamp((0.42 - m_f16 * 4.0 / m_sr) * 12.0, 0.0, 1.0) * m_s4 + m_A5 * (1.0 + m_ljv * 0.3305) * gen::clamp((0.42 - m_f16 * 5.0 / m_sr) * 12.0, 0.0, 1.0) * m_s5 + m_A6 * (1.0 + m_ljv * 0.3962) * gen::clamp((0.42 - m_f16 * 6.0 / m_sr) * 12.0, 0.0, 1.0) * m_s6 + m_A8 * (1.0 + m_ljv * 0.5000) * gen::clamp((0.42 - m_f16 * 8.0 / m_sr) * 12.0, 0.0, 1.0) * m_s8 + m_A10 * (1.0 + m_ljv * 0.5805) * gen::clamp((0.42 - m_f16 * 10.0 / m_sr) * 12.0, 0.0, 1.0) * m_s10 + m_A12 * (1.0 + m_ljv * 0.6462) * gen::clamp((0.42 - m_f16 * 12.0 / m_sr) * 12.0, 0.0, 1.0) * m_s12 + m_A16 * (1.0 + m_ljv * 0.7500) * gen::clamp((0.42 - m_f16 * 16.0 / m_sr) * 12.0, 0.0, 1.0) * m_s16 + m_A20 * (1.0 + m_ljv * 0.8305) * gen::clamp((0.42 - m_f16 * 20.0 / m_sr) * 12.0, 0.0, 1.0) * m_s20 + m_A24 * (1.0 + m_ljv * 0.8962) * gen::clamp((0.42 - m_f16 * 24.0 / m_sr) * 12.0, 0.0, 1.0) * m_s24 + m_A32 * (1.0 + m_ljv * 1.0000) * gen::clamp((0.42 - m_f16 * 32.0 / m_sr) * 12.0, 0.0, 1.0) * m_s32;
          m_v7_pc = gen::wrap(m_v7_pc + m_f16 * 2.0 * std::pow(2.0, m_celc / 1200.0) / m_sr, 0.0, 1.0);
          m_xc = gen::kTwoPi * m_v7_pc;
          m_celv = (std::sin(m_xc) + 0.3 * m_b * std::sin(2.0 * m_xc)) * m_celm * 0.7;
          m_dr = gen::clamp(m_f16 * 2.0 / m_sr, 0.0, 0.45);
          m_v7_pr = m_v7_pr + m_dr;
          if (m_v7_pr >= 1.0) { m_v7_pr = m_v7_pr - 1.0; }
          m_qr = m_v7_pr;
        m_blr = m_qr < m_dr ? (m_qr / m_dr) * 2.0 - (m_qr / m_dr) * (m_qr / m_dr) - 1.0 : (m_qr > 1.0 - m_dr ? ((m_qr - 1.0) / m_dr) * ((m_qr - 1.0) / m_dr) + ((m_qr - 1.0) / m_dr) * 2.0 + 1.0 : 0.0);
          m_saw = 2.0 * m_qr - 1.0 - m_blr;
        m_v7_rlg = std::tan(gen::kPi * gen::clamp(m_f16 * 2.0 * (2.5 + 6.0 * ton), 10.0, m_sr * 0.45) / m_sr);
        m_v7_rlx = m_saw;
        m_v7_rl1 = 1.0 / (1.0 + m_v7_rlg * (m_v7_rlg + (0.7)));
        m_v7_rlv3 = m_v7_rlx - m_v7_rl_b;
        m_v7_rlv1 = m_v7_rl1 * m_v7_rl_a + m_v7_rlg * m_v7_rl1 * m_v7_rlv3;
        m_v7_rlv2 = m_v7_rl_b + m_v7_rlg * m_v7_rlv1;
        m_v7_rl_a = 2.0 * m_v7_rlv1 - m_v7_rl_a;
        m_v7_rl_b = 2.0 * m_v7_rlv2 - m_v7_rl_b;
        m_rlp = m_v7_rlv2;
          m_nz = rng.next() * (m_v7_ch * chf * 1.4 + vind * 0.07 * std::sqrt(m_v7_e));
        m_v7_bpg = std::tan(gen::kPi * gen::clamp(gen::min(m_f16 * 6.0, 9000.0), 10.0, m_sr * 0.45) / m_sr);
        m_v7_bpx = m_nz;
        m_v7_bp1 = 1.0 / (1.0 + m_v7_bpg * (m_v7_bpg + (0.32)));
        m_v7_bpv3 = m_v7_bpx - m_v7_bp_b;
        m_v7_bpv1 = m_v7_bp1 * m_v7_bp_a + m_v7_bpg * m_v7_bp1 * m_v7_bpv3;
        m_v7_bpv2 = m_v7_bp_b + m_v7_bpg * m_v7_bpv1;
        m_v7_bp_a = 2.0 * m_v7_bpv1 - m_v7_bp_a;
        m_v7_bp_b = 2.0 * m_v7_bpv2 - m_v7_bp_b;
        m_luft = m_v7_bpv1;
          m_amp = m_v7_e * m_tampv * (1.0 - vela + vela * m_v7_vel) * m_ug;
          m_sv = ((m_pipa + m_celv + m_rlp * trp * 0.6) * m_norm + m_luft * 0.5) * m_amp;
          m_sida = gen::wrap(std::floor(n7 + 0.5), 0.0, 2.0) < 1.0 ? 1.0 : -1.0;
          m_xL = m_xL + m_sv * (1.0 - m_spread * gen::max(0.0, m_sida));
          m_xR = m_xR + m_sv * (1.0 - m_spread * gen::max(0.0, -m_sida));
