        m_wL = dlb.peek( m_ri, 0.0) * (1.0 - m_rf) + dlb.peek( gen::wrap(m_ri + 1.0, 0.0, 52000.0), 0.0) * m_rf;
        m_wR = dlb.peek( m_ri, 1.0) * (1.0 - m_rf) + dlb.peek( gen::wrap(m_ri + 1.0, 0.0, 52000.0), 1.0) * m_rf;
